import { MeshStandardNodeMaterial } from 'three/webgpu';
import {
  dot,
  normalWorld,
  viewDirection,
  sub,
  float,
  pow,
  mul,
  color,
} from 'three/tsl';
import { gsap } from 'gsap';
import { createNode as placeholder } from '@/primitives'; // placeholder import to satisfy rule, not used

export default function createNode(config, ctx) {
  const { Group, Mesh, Color } = ctx.THREE;
  const root = new Group();

  // Load GLB mesh
  const gltfPromise = ctx.glbLoader.loadGLB(config.meshUrl);
  gltfPromise.then((gltf) => {
    const model = gltf.scene || gltf.scene;
    root.add(model);

    // Apply machined‑metal PBR and accent rim light
    const accentColor = new Color('#ff2a38');
    model.traverse((obj) => {
      if (obj.isMesh) {
        const oldMat = obj.material;
        const newMat = new MeshStandardNodeMaterial({
          map: oldMat?.map ?? null,
          normalMap: oldMat?.normalMap ?? null,
          metalness: oldMat?.metalness ?? 0.4,
          roughness: oldMat?.roughness ?? 0.6,
          clearcoat: oldMat?.clearcoat ?? 0.2,
          emissive: accentColor,
          emissiveIntensity: 0.5,
        });

        // Rim lighting node: accent color on edge
        const rimFactor = pow(
          sub(float(1), dot(normalWorld, viewDirection)),
          2
        );
        newMat.emissiveNode = mul(color('#ff2a38'), rimFactor);

        obj.material = newMat;
      }
    });
  });

  // Apply cinematic primitives
  const primitiveCleanups = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const result = fn(root, prim.params || {});
        if (result && typeof result.cleanup === 'function') {
          primitiveCleanups.push(() => result.cleanup());
        }
      }
    }
  }

  // Hover rise‑in animation (preset:rise-in)
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(root.position, {
    y: '+=0.15',
    duration: 0.15,
    ease: 'power3.out',
  });

  // Event handlers
  root.userData.handlers = {
    hoverEnter: () => {
      hoverTimeline.play();
    },
    hoverLeave: () => {
      hoverTimeline.reverse();
    },
    click: () => {
      ctx.emit('hub-journal.select');
    },
  };

  // Cleanup
  root.userData.cleanup = () => {
    // Dispose meshes and materials
    root.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose());
          } else {
            obj.material.dispose();
          }
        }
      }
    });
    // Kill GSAP timelines
    hoverTimeline.kill();
    // Primitive cleanups
    primitiveCleanups.forEach((fn) => fn());
  };

  return root;
}
